def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/archeology/input/roman_cities.csv'
    return pd.read_csv(path)

def process(romanCities):
    import pandas as pd

    # "sources" interpreted as distinct bibliography source strings in the dataset
    # (the file contains a "Select Bibliography" column listing sources per city)
    s = romanCities['Select Bibliography']
    return pd.DataFrame({'unique_sources': [s.dropna().nunique()]})
